import{d as s,C as n,o as g,c as h,E as i,a3 as a}from"./chunks/framework.Q4yG9rk_.js";const y=JSON.parse('{"title":"无妄卦","description":"第二十五卦·天雷无妄——天下雷行，物与无妄。无妄不是无为，是「为」先被「时」校准过；眚不是天降之灾，是心生执念之后视野失真。","frontmatter":{"title":"无妄卦","description":"第二十五卦·天雷无妄——天下雷行，物与无妄。无妄不是无为，是「为」先被「时」校准过；眚不是天降之灾，是心生执念之后视野失真。","category":"hexagram","aliases":["无妄","天雷无妄"],"source":["《周易》"],"outline":[2,3]},"headers":[],"relativePath":"yijing/hexagrams/25-tianleiwuwang.md","filePath":"yijing/hexagrams/25-tianleiwuwang.md","lastUpdated":1789987057000}'),p={name:"yijing/hexagrams/25-tianleiwuwang.md"},b=s({...p,setup(u){const o=[{id:"wuwang",term:"无妄",pinyin:"wú wàng",meaning:"不是「无为」，是「为」先被「时」校准过。妄为心生执念、私欲、强求。"},{id:"sheng",term:"眚",pinyin:"shěng",meaning:"字形从目从生，眼生翳障。不是外部降临的灾祸，而是心生执念导致视野失真、从而引发的必然过失。",context:"与乾卦上九「亢龙有悔」的「悔」相对：悔是知道自己偏了，眚是连自己偏没偏都已看不清。"},{id:"zi",term:"菑",pinyin:"zī",meaning:"初耕田、开荒。一说一年之田曰菑。"},{id:"she",term:"畲",pinyin:"shē",meaning:"熟田；一说耕作三年之田曰畲。"},{id:"genghuo",term:"不耕获",pinyin:"bù gēng huò",meaning:"耕种而不图收获。六二以此言「为」而无所算计。"},{id:"feizheng",term:"匪正",pinyin:"fěi zhèng",meaning:"不正、偏离正道。匪即非。"},{id:"maodui",term:"茂对时",pinyin:"mào duì shí",meaning:"茂即努力、勤勉；勉力顺应天时。象传「先王以茂对时育万物」。"},{id:"dezhi",term:"得志",pinyin:"dé zhì",meaning:"志得其所——不是「达成目标」，而是出发点与最真的心志对齐。"},{id:"wuyao",term:"勿药",pinyin:"wù yào",meaning:"不用药、不去试药自证。"},{id:"guyouzhi",term:"固有之",pinyin:"gù yǒu zhī",meaning:"本来就具备的。象传「可贞无咎，固有之也」。"},{id:"jiu",term:"咎",pinyin:"jiù",meaning:"灾祸、罪过。"},{id:"you",term:"攸",pinyin:"yōu",meaning:"所、往。「不利有攸往」即不宜有所往。"}],e=[{position:"初九",type:"yang",text:"无妄，往吉。",xiang:"无妄之往，得志也。",textModern:"出发时心无妄念，前行则吉。",xiangModern:"无妄而往，是志得其所。"},{position:"六二",type:"yin",text:"不耕获，不菑畲，则利有攸往。",xiang:"不耕获，未富也。",textModern:"耕种不图收获，开荒不图新田，如此则利于前行。",xiangModern:"不图收获，所以未把富放在心上。"},{position:"六三",type:"yin",text:"无妄之灾，或系之牛，行人之得，邑人之灾。",xiang:"行人得牛，邑人灾也。",textModern:"没有做错什么却招来灾祸：有人把牛系在那里，过路的人牵走了，账却算在村人头上。",xiangModern:"过路人得了牛，村人却因此受灾。"},{position:"九四",type:"yang",text:"可贞，无咎。",xiang:"可贞无咎，固有之也。",textModern:"可以持守正道，便没有灾祸。",xiangModern:"守正而无咎，是因为这份能力本来就具备。"},{position:"九五",type:"yang",text:"无妄之疾，勿药有喜。",xiang:"无妄之药，不可试也。",textModern:"无端生病，不必用药，自会好转。",xiangModern:"无妄之药，是不可以去试的。"},{position:"上九",type:"yang",text:"无妄，行有眚，无攸利。",xiang:"无妄之行，穷之灾也。",textModern:"即便起点无妄，走到这里若还要妄动，便生遮蔽，无所利。",xiangModern:"无妄而行，是穷极处的灾。"}];return(m,t)=>{const r=n("DaoHexagramViewer"),l=n("DaoHexagramYaoCards"),d=n("DaoKeywordCards");return g(),h("div",null,[i(r,{name:"无妄",fullName:"天雷无妄",upper:"☰",lower:"☳",guaCi:"无妄，元亨利贞。其匪正有眚，不利有攸往。",pinyin:["wú","wàng"],element:"木",direction:"东南",insight:"天下雷行，万物各得其本然。无妄不是无为，是先把「为」对准「时」——先有茂对时的真实作为，才谈得上自然无为的结果。",guaSlug:"25tianleiwuwang",lines:e}),t[0]||(t[0]=a("",11)),i(l,{element:"木",guaSlug:"25tianleiwuwang",glossary:o,items:e}),t[1]||(t[1]=a("",29)),i(d,{title:"字词释义",items:[{term:"无妄",pinyin:["wú","wàng"],meaning:"不是「无为」，是「为」先被「时」校准过。妄为心生执念、私欲、强求。"},{term:"眚",pinyin:["shěng"],meaning:"字形从目从生，眼生翳障。不是外部降临的灾祸，而是心生执念导致视野失真、从而引发的必然过失。"},{term:"菑",pinyin:["zī"],meaning:"初耕田、开荒。一说一年之田曰菑。"},{term:"畲",pinyin:["shē"],meaning:"熟田；一说耕作三年之田曰畲。"},{term:"不耕获",pinyin:["bù","gēng","huò"],meaning:"耕种而不图收获。六二以此言「为」而无所算计。"},{term:"匪正",pinyin:["fěi","zhèng"],meaning:"不正、偏离正道。匪即非。「其匪正有眚」。"},{term:"茂对时",pinyin:["mào","duì","shí"],meaning:"茂即努力、勤勉；勉力顺应天时。象传「先王以茂对时育万物」。"},{term:"得志",pinyin:["dé","zhì"],meaning:"志得其所——不是「达成目标」，而是出发点与最真的心志对齐。"},{term:"勿药",pinyin:["wù","yào"],meaning:"不用药、不去试药自证。九五「无妄之疾，勿药有喜」。"},{term:"固有之",pinyin:["gù","yǒu","zhī"],meaning:"本来就具备的。象传「可贞无咎，固有之也」。"},{term:"天命不祐",pinyin:["tiān","mìng","bù","yòu"],meaning:"天命不保佑。彖传「天命不祐，行矣哉」。"},{term:"咎",pinyin:["jiù"],meaning:"灾祸、罪过。"},{term:"攸",pinyin:["yōu"],meaning:"所、往。「不利有攸往」即不宜有所往。"}]}),t[2]||(t[2]=a("",25))])}}});export{y as __pageData,b as default};
